import torch
import torch.nn as nn
import triton
import triton.language as tl


def _get_autotune_configs():
    configs = [
        triton.Config(
            {
                "BLOCK_M": 32,
                "BLOCK_N": 32,
                "BLOCK_K": 32,
                "GROUP_SIZE_M": 1,
                "EVEN_M": False,
                "EVEN_N": False,
                "EVEN_K": False,
            }
        ),
    ]

    return configs


@triton.autotune(
    configs=_get_autotune_configs(),
    key=["M", "N", "K"],
)
@triton.jit
def _linear_div_gelu_kernel_packed_rhs(
    x_ptr,
    w_ptr,
    b_ptr,
    out_ptr,
    M,
    N,
    K,
    stride_xm: tl.constexpr,
    stride_xk: tl.constexpr,
    stride_wk: tl.constexpr,
    stride_wn: tl.constexpr,
    stride_b,
    stride_om: tl.constexpr,
    stride_on: tl.constexpr,
    divisor,
    BLOCK_M: tl.constexpr,
    BLOCK_N: tl.constexpr,
    BLOCK_K: tl.constexpr,
    GROUP_SIZE_M: tl.constexpr,
    grf_mode: tl.constexpr,
    EVEN_M: tl.constexpr,
    EVEN_N: tl.constexpr,
    EVEN_K: tl.constexpr,
):
    pid = tl.program_id(0)

    num_pid_m = tl.cdiv(M, BLOCK_M)
    num_pid_n = tl.cdiv(N, BLOCK_N)

    num_pid_in_group = GROUP_SIZE_M * num_pid_n
    group_id = pid // num_pid_in_group
    first_pid_m = group_id * GROUP_SIZE_M
    group_size_m = tl.minimum(num_pid_m - first_pid_m, GROUP_SIZE_M)
    pid_in_group = pid % num_pid_in_group
    pid_m = first_pid_m + (pid_in_group % group_size_m)
    pid_n = pid_in_group // group_size_m

    m_start = pid_m * BLOCK_M
    n_start = pid_n * BLOCK_N

    x_desc = tl.make_tensor_descriptor(
        base=x_ptr,
        shape=(M, K),
        strides=(stride_xm, stride_xk),
        block_shape=(BLOCK_M, BLOCK_K),
    )
    w_desc = tl.make_tensor_descriptor(
        base=w_ptr,
        shape=(K, N),
        strides=(stride_wk, stride_wn),
        block_shape=(BLOCK_K, BLOCK_N),
    )

    acc = tl.zeros((BLOCK_M, BLOCK_N), dtype=tl.float32)
    for off_k in range(0, K, BLOCK_K):
        a = x_desc.load([m_start, off_k])
        b = w_desc.load([off_k, n_start])
        acc += tl.dot(a, b)

    offs_n = n_start + tl.arange(0, BLOCK_N)
    bias = tl.load(b_ptr + offs_n * stride_b, mask=offs_n < N, other=0.0)
    acc = (acc + bias[None, :]) / divisor

    inv_sqrt2 = 0.7071067811865475
    y = 0.5 * acc * (1.0 + tl.math.erf(acc * inv_sqrt2))

    out_desc = tl.make_tensor_descriptor(
        base=out_ptr,
        shape=(M, N),
        strides=(stride_om, stride_on),
        block_shape=(BLOCK_M, BLOCK_N),
    )
    out_desc.store([m_start, n_start], y.to(out_ptr.type.element_ty))


def kernel_function(input, weight_packed, bias, divisor=10.0):
    """
    Fused Triton kernel for output = GELU((input @ weight_packed + bias) / divisor)
    input: [M, K] fp16/bf16 on device
    weight_packed: [K, N] fp16/bf16 on device
    bias: [N] fp16/bf16/fp32 on device
    """
    target_dtype = (
        input.dtype
        if input.dtype in (torch.float16, torch.bfloat16)
        else torch.bfloat16
    )
    x_xpu = input.to(dtype=target_dtype).contiguous()
    w_xpu = weight_packed.to(dtype=target_dtype).contiguous()
    b_xpu = bias.to(dtype=target_dtype).contiguous()

    M, K = x_xpu.shape
    K_w, N = w_xpu.shape
    assert K == K_w and b_xpu.shape[0] == N

    out = torch.empty((M, N), device=x_xpu.device, dtype=target_dtype)

    grid = lambda META: (
        triton.cdiv(M, META["BLOCK_M"]) * triton.cdiv(N, META["BLOCK_N"]),
    )

    _linear_div_gelu_kernel_packed_rhs[grid](
        x_xpu,
        w_xpu,
        b_xpu,
        out,
        M,
        N,
        K,
        x_xpu.stride(0),
        x_xpu.stride(1),
        w_xpu.stride(0),
        w_xpu.stride(1),
        b_xpu.stride(0),
        out.stride(0),
        out.stride(1),
        float(divisor),
        grf_mode="auto",
    )
    return out


batch_size = 1024
input_size = 8192
output_size = 8192
divisor = 10.0


def get_inputs():
    return [torch.rand(batch_size, input_size, dtype=torch.bfloat16)]


def get_init_inputs():
    return [input_size, output_size, divisor]


class Model(nn.Module):
    def __init__(self, input_size, output_size, divisor):
        super().__init__()
        self.linear = nn.Linear(input_size, output_size)
        self.divisor = divisor
        self.input_size = input_size
        self.output_size = output_size
        self._packed_w = None
        self._bias_packed = None
        self._packed_dtype = None

    def _lazy_init(self, device, dtype):
        target_dtype = (
            dtype if dtype in (torch.float16, torch.bfloat16) else torch.bfloat16
        )
        if (
            self._packed_w is None
            or self._bias_packed is None
            or self._packed_dtype != target_dtype
        ):
            w = self.linear.weight.detach().to(device, dtype=target_dtype).contiguous()
            b = self.linear.bias.detach().to(device, dtype=target_dtype).contiguous()
            self._packed_w = w.t().contiguous()  # [K, N]
            self._bias_packed = b
            self._packed_dtype = target_dtype

    def forward(self, x):
        target_dtype = (
            x.dtype if x.dtype in (torch.float16, torch.bfloat16) else torch.bfloat16
        )
        self._lazy_init(x.device, x.dtype)
        x_xpu = x.to(dtype=target_dtype).contiguous()
        return kernel_function(x_xpu, self._packed_w, self._bias_packed, self.divisor)
